package main

import (
	"fmt"
	"unicode"
)

func main() {
	s := "Go 1.16 Is Great!"
	var letters, digits, spaces, vowels int
	for _, r := range s {
		switch {
		case unicode.IsLetter(r):
			letters++
		case unicode.IsDigit(r):
			digits++
		case unicode.IsSpace(r):
			spaces++
		}
		switch unicode.ToLower(r) {
		case 'a', 'e', 'i', 'o', 'u':
			vowels++
		}
	}
	fmt.Printf("letters=%d digits=%d spaces=%d vowels=%d\n", letters, digits, spaces, vowels)
}

