package main

import (
	"fmt"
	"unicode"
)

func main() {
	s := "Hello, World 2024!"
	var upper, lower, digits, punct, vowels int
	for _, r := range s {
		switch {
		case unicode.IsUpper(r):
			upper++
		case unicode.IsLower(r):
			lower++
		case unicode.IsDigit(r):
			digits++
		case unicode.IsPunct(r):
			punct++
		}
		switch unicode.ToLower(r) {
		case 'a', 'e', 'i', 'o', 'u':
			vowels++
		}
	}
	fmt.Printf("upper=%d lower=%d digits=%d punct=%d vowels=%d\n", upper, lower, digits, punct, vowels)
}

example.code:
package main

import "fmt"

func main() {
	runes := []rune("Gopher")
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	fmt.Println(string(runes))

	shifted := []rune("abc xyz")
	for i, r := range shifted {
		if r >= 'a' && r <= 'z' {
			shifted[i] = 'a' + (r-'a'+3)%26
		}
	}
	fmt.Println(string(shifted))

	word := "go"
	b := []byte(word)
	b[0] = 'G'
	fmt.Println(word, string(b))
}

