package main

import (
	"fmt"
	"strings"
	"unicode"
)

func main() {
	var sb strings.Builder
	for _, word := range strings.Fields("portable network graphics") {
		first := []rune(word)[0]
		sb.WriteRune(unicode.ToUpper(first))
	}
	sb.WriteByte(' ')
	sb.WriteString("format")
	fmt.Println(sb.String(), sb.Len())
}

