package main

import (
	"fmt"
	"strings"
	"unicode"
)

func main() {
	name := "grace brewster hopper"
	var sb strings.Builder
	for _, word := range strings.Fields(name) {
		first := []rune(word)[0]
		sb.WriteRune(unicode.ToUpper(first))
		sb.WriteByte('.')
	}
	fmt.Println(sb.String(), sb.Len())
}
